+          svc.shutdown();
+        } catch (Exception e) {
+          log.error("Unabled to get destination tracer hosts in ZooKeeper, will retry in 5 seconds", e);
+          // We failed to connect to ZK, try again in 5seconds
+          svc.schedule(this, retryPause, TimeUnit.MILLISECONDS);
+        }
+      }
+    };
+
+    // Start things off
+    task.run();
+  }
